	@Test
	public void threeTypeMappers() throws Exception {
		ObjectMapper om = new ObjectMapper();

		// 打印全部属性
		JsonMapper normalBinder = JsonMapper.defaultMapper();
		TestBean bean = new TestBean("A");
		assertThat(om.readTree(normalBinder.toJson(bean)))
				.isEqualTo(om.readTree("{\"name\":\"A\",\"defaultValue\":\"hello\",\"nullValue\":null,\"emptyValue\":[]}"));

		// 不打印nullValue属性
		JsonMapper nonNullMapper = JsonMapper.nonNullMapper();
		assertThat(om.readTree(nonNullMapper.toJson(bean)))
				.isEqualTo(om.readTree("{\"name\":\"A\",\"defaultValue\":\"hello\",\"emptyValue\":[]}"));

		// 不打印nullValue与empty的属性
		JsonMapper nonEmptyMapper = JsonMapper.nonEmptyMapper();
		assertThat(om.readTree(nonEmptyMapper.toJson(bean))).isEqualTo(om.readTree("{\"name\":\"A\",\"defaultValue\":\"hello\"}"));

		TestBean nonEmptyBean = nonEmptyMapper.fromJson("{\"name\":\"A\",\"defaultValue\":\"hello\"}", TestBean.class);
		assertThat(nonEmptyBean.getEmptyValue()).isEmpty();
	}
