//<fix start>
    @Test
    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        String baseStr = this.toBaseString(instance1);
        String expectedFields = "staticInt=12345,staticString=staticString";
        String expected = baseStr + "[" + expectedFields + "]";

        Function<String, String> normalize = actual -> {
            int start = actual.indexOf('[');
            int end = actual.lastIndexOf(']');
            if (start == -1 || end == -1) return actual;
            String prefix = actual.substring(0, start + 1);
            String suffix = actual.substring(end);
            String fields = actual.substring(start + 1, end);
            String[] arr = fields.split(",");
            Arrays.sort(arr);
            return prefix + String.join(",", arr) + suffix;
        };

        assertEquals(expected, normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(expected, normalize.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(expected, normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(expected, normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
