//<fix start>
    @Test
    public void testPerson() {
        final Person p = new Person();
        p.name = "John Doe";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        final String pBaseStr = p.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p));
        final String pJobStr  = p.job.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p.job));

        String actual = new ReflectionToStringBuilder(p, new RecursiveToStringStyle()).toString();
        int start = actual.indexOf('[');
        int end = actual.lastIndexOf(']');
        String actualPrefix = actual.substring(0, start + 1);
        String actualFieldsStr = actual.substring(start + 1, end);

        String[] actualFields = actualFieldsStr.split(",");
        java.util.Arrays.sort(actualFields);
        StringBuilder actualSortedBuilder = new StringBuilder();
        for (int i = 0; i < actualFields.length; i++) {
            if (i > 0) actualSortedBuilder.append(",");
            actualSortedBuilder.append(actualFields[i]);
        }
        String actualSorted = actualSortedBuilder.toString();

        String expectedFieldsStr = "name=John Doe,age=33,smoker=false,job=" + pJobStr + "[title=Manager]";
        String[] expectedFields = expectedFieldsStr.split(",");
        java.util.Arrays.sort(expectedFields);
        StringBuilder expectedSortedBuilder = new StringBuilder();
        for (int i = 0; i < expectedFields.length; i++) {
            if (i > 0) expectedSortedBuilder.append(",");
            expectedSortedBuilder.append(expectedFields[i]);
        }
        String expectedSorted = expectedSortedBuilder.toString();

        assertEquals(pBaseStr + "[" + expectedSorted + "]", actualPrefix + actualSorted + "]");
    }
