    @Test
    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();

        java.util.function.Function<String, String> normalize = s -> {
            int start = s.indexOf('[');
            int end = s.lastIndexOf(']');
            if (start == -1 || end == -1) return s;
            String prefix = s.substring(0, start + 1);
            String suffix = s.substring(end);
            String fields = s.substring(start + 1, end);
            java.util.List<String> parts = java.util.Arrays.asList(fields.split(","));
            java.util.Collections.sort(parts);
            return prefix + String.join(",", parts) + suffix;
        };

        assertEquals(
            normalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]"),
            normalize.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            normalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            normalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
    }
