        for (int i = 0; i < fieldsStr1.length(); i++) {
            char c = fieldsStr1.charAt(i);
            if (c == '{') depth1++;
            else if (c == '}') depth1--;
            else if (c == ',' && depth1 == 0) {
                String field = fieldsStr1.substring(start1, i);
                int eq = field.indexOf('=');
                actualFields1.put(field.substring(0, eq), field.substring(eq + 1));
                start1 = i + 1;
            }
        }
        String lastField1 = fieldsStr1.substring(start1);
        int eq1 = lastField1.indexOf('=');
        actualFields1.put(lastField1.substring(0, eq1), lastField1.substring(eq1 + 1));

        Map<String, String> expectedFields1 = new HashMap<>();
        expectedFields1.put("elementData", "{<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>}");
        expectedFields1.put("size", "0");
        expectedFields1.put("modCount", "0");

        assertEquals(expectedFields1, actualFields1);

        final String toStringWithoutTransients = ToStringBuilder.reflectionToString(list, null, false);
        String fieldsStr2 = toStringWithoutTransients.substring(baseString.length() + 1, toStringWithoutTransients.length() - 1);

        Map<String, String> actualFields2 = new HashMap<>();
