//<fix start>
    @Test
    public void testReflectionHierarchy() {
        class FieldAsserter {
            void assertFields(String actual, String expectedFieldsStr, String baseStr) {
                String expectedPrefix = baseStr + "[";
                assertTrue(actual.startsWith(expectedPrefix) && actual.endsWith("]"), "Unexpected format: " + actual);
                String[] actualFields = actual.substring(expectedPrefix.length(), actual.length() - 1).split(",");
                Arrays.sort(actualFields);
                String[] expectedFields = expectedFieldsStr.split(",");
                Arrays.sort(expectedFields);
                assertEquals(Arrays.toString(expectedFields), Arrays.toString(actualFields));
            }
        }
        FieldAsserter asserter = new FieldAsserter();

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA), "a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA, null), "a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA, null, false), "a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA, null, true), "a=a,transientA=t", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA, null, false, null), "a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA, null, false, Object.class), "a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class), "a=a", baseString);

        final ReflectionTestFixtureB baseB = new ReflectionTestFixtureB();
        baseString = this.toBaseString(baseB);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseB), "b=b,a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseB), "b=b,a=a", baseString);
        asserter.assertFields(ToStringBuilder.reflectionToString(baseB, null), "b=b,a=a", baseString);
