    @Test
    public void testReflectionHierarchy() {
        Function<String, String> normalize = s -> {
            int start = s.indexOf('[');
            int end = s.lastIndexOf(']');
            if (start == -1 || end == -1) {
                return s;
            }
            String prefix = s.substring(0, start + 1);
            String suffix = s.substring(end);
            String fields = s.substring(start + 1, end);
            if (fields.isEmpty()) {
                return prefix + suffix;
            }
            String[] parts = fields.split(",");
            Arrays.sort(parts);
            return prefix + String.join(",", parts) + suffix;
        };

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);
        assertEquals(normalize.apply(baseString + "[a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseA)));
        assertEquals(normalize.apply(baseString + "[a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseA, null)));
        assertEquals(normalize.apply(baseString + "[a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseA, null, false)));
        assertEquals(normalize.apply(baseString + "[a=a,transientA=t]"), normalize.apply(ToStringBuilder.reflectionToString(baseA, null, true)));
        assertEquals(normalize.apply(baseString + "[a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseA, null, false, null)));
        assertEquals(normalize.apply(baseString + "[a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseA, null, false, Object.class)));
        assertEquals(normalize.apply(baseString + "[a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class)));

        final ReflectionTestFixtureB baseB = new ReflectionTestFixtureB();
        baseString = this.toBaseString(baseB);
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB)));
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB)));
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null)));
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null, false)));
        assertEquals(normalize.apply(baseString + "[b=b,transientB=t,a=a,transientA=t]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null, true)));
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null, false, null)));
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null, false, Object.class)));
        assertEquals(normalize.apply(baseString + "[b=b,a=a]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null, false, ReflectionTestFixtureA.class)));
        assertEquals(normalize.apply(baseString + "[b=b]"), normalize.apply(ToStringBuilder.reflectionToString(baseB, null, false, ReflectionTestFixtureB.class)));
    }
