//<fix start>
	@Test
	public void testImport() throws Exception {
		ClassPathResource resource = new ClassPathResource("importing.xsd", getClass());
		CommonsXsdSchemaCollection schemaCollection = new CommonsXsdSchemaCollection(resource);
		schemaCollection.setInline(true);
		schemaCollection.afterPropertiesSet();
		definition.setSchemaCollection(schemaCollection);

		definition.setPortTypeName("Order");
		definition.setTargetNamespace("http://www.springframework.org/spring-ws/import/definitions");
		definition.setLocationUri("http://localhost:8080/");
		definition.afterPropertiesSet();

		DOMResult domResult = new DOMResult();
		transformer.transform(definition.getSource(), domResult);

		Document result = (Document) domResult.getNode();
		Document expected = documentBuilder.parse(getClass().getResourceAsStream("import-inline.wsdl"));

		class NodeSorter {
			void sort(org.w3c.dom.Node node) {
				if (node == null) return;
				org.w3c.dom.NodeList children = node.getChildNodes();
				java.util.List<org.w3c.dom.Node> childList = new java.util.ArrayList<>();
				for (int i = 0; i < children.getLength(); i++) {
					org.w3c.dom.Node child = children.item(i);
					if (child.getNodeType() == org.w3c.dom.Node.TEXT_NODE && child.getTextContent().trim().isEmpty()) {
						continue;
					}
					childList.add(child);
				}
				childList.sort((n1, n2) -> {
					if (n1.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE && n2.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
						org.w3c.dom.Element e1 = (org.w3c.dom.Element) n1;
						org.w3c.dom.Element e2 = (org.w3c.dom.Element) n2;
						int cmp = e1.getTagName().compareTo(e2.getTagName());
						if (cmp != 0) return cmp;
						String name1 = e1.getAttribute("name");
						String name2 = e2.getAttribute("name");
						if (name1 != null && !name1.isEmpty() && name2 != null && !name2.isEmpty()) {
							return name1.compareTo(name2);
						}
						String loc1 = e1.getAttribute("schemaLocation");
						String loc2 = e2.getAttribute("schemaLocation");
						if (loc1 != null && !loc1.isEmpty() && loc2 != null && !loc2.isEmpty()) {
							return loc1.compareTo(loc2);
						}
						String loc3 = e1.getAttribute("location");
						String loc4 = e2.getAttribute("location");
						if (loc3 != null && !loc3.isEmpty() && loc4 != null && !loc4.isEmpty()) {
							return loc3.compareTo(loc4);
						}
						return 0;
					}
					return Integer.compare(childList.indexOf(n1), childList.indexOf(n2));
				});
				while (node.hasChildNodes()) {
					node.removeChild(node.getFirstChild());
				}
				for (org.w3c.dom.Node child : childList) {
					node.appendChild(child);
					sort(child);
				}
			}
		}

		NodeSorter sorter = new NodeSorter();
		sorter.sort(expected.getDocumentElement());
		sorter.sort(result.getDocumentElement());

		assertXMLEqual("Invalid WSDL built", expected, result);
	}
