            this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"
        };

        for (int i = 0; i < actuals.length; i++) {
            String expected = expecteds[i];
            String actual = actuals[i];
            int start = expected.indexOf('[');
            int end = expected.lastIndexOf(']');
            assertEquals(expected.substring(0, start + 1), actual.substring(0, start + 1));
            assertEquals(expected.substring(end), actual.substring(actual.lastIndexOf(']')));

            String expectedFields = expected.substring(start + 1, end);
