//<fix start>
    @Test
    public void stringArray() {
        final WithArrays wa = new WithArrays();
        wa.stringArray = new String[] { "a", "A" };

        String actual = toString(wa);
        String prefix = getClassPrefix(wa) + "[" + BR;
        String suffix = BR + "]";

        org.junit.jupiter.api.Assertions.assertTrue(actual.startsWith(prefix));
        org.junit.jupiter.api.Assertions.assertTrue(actual.endsWith(suffix));

        String middle = actual.substring(prefix.length(), actual.length() - suffix.length());
        // Split by top-level fields (exactly 2 spaces indentation followed by a non-whitespace character)
        String[] rawFields = middle.split("(?m)^  (?=\\S)");

        List<String> fieldList = new ArrayList<>();
        for (int i = 1; i < rawFields.length; i++) {
            String f = rawFields[i];
            // Normalize trailing commas and line separators
            if (f.endsWith("," + BR)) {
                f = f.substring(0, f.length() - 1 - BR.length());
            } else if (f.endsWith(",")) {
                f = f.substring(0, f.length() - 1);
            }
            fieldList.add(f);
        }

        // Sort fields to ensure deterministic comparison regardless of reflection order
        java.util.Collections.sort(fieldList);

        String expectedMiddle = String.join("," + BR + "  ", fieldList);
        String exp = prefix + "  " + expectedMiddle + suffix;

        assertEquals(exp, actual);
    }
//<fix end>
