//<fix start>
    @Test
    public void stringArray() {
        final WithArrays wa = new WithArrays();
        wa.stringArray = new String[] { "a", "A" };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray=<null>," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray={" + BR
                   + "    a," + BR
                   + "    A" + BR
                   + "  }" + BR
                   + "]";

        String prefix = getClassPrefix(wa) + "[" + BR;
        String suffix = BR + "]";
        String actual = toString(wa);

        if (!actual.startsWith(prefix) || !actual.endsWith(suffix)) {
            assertEquals(exp, actual);
            return;
        }

        Map<String, String> expMap = new LinkedHashMap<>();
        Map<String, String> actMap = new LinkedHashMap<>();

        String expBody = exp.substring(prefix.length(), exp.length() - suffix.length());
        for (String part : expBody.split("\n  (?=[a-zA-Z_$])")) {
            String p = part.startsWith("  ") ? part.substring(2) : part;
            if (p.endsWith(",")) p = p.substring(0, p.length() - 1);
            int eqIdx = p.indexOf('=');
            if (eqIdx > 0) expMap.put(p.substring(0, eqIdx), p.substring(eqIdx + 1));
        }

        String actBody = actual.substring(prefix.length(), actual.length() - suffix.length());
        for (String part : actBody.split("\n  (?=[a-zA-Z_$])")) {
            String p = part.startsWith("  ") ? part.substring(2) : part;
            if (p.endsWith(",")) p = p.substring(0, p.length() - 1);
            int eqIdx = p.indexOf('=');
            if (eqIdx > 0) actMap.put(p.substring(0, eqIdx), p.substring(eqIdx + 1));
        }

        assertEquals(expMap, actMap);
    }
