        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    Schema expected = new Schema.Parser().parse(expectedJson);
    Schema actual = ReflectData.get().getSchema(DocTest.class);

    class SchemaComparator {
        void assertEqual(Schema s1, Schema s2) {
            assertEquals(s1.getType(), s2.getType());
            assertEquals(s1.getName(), s2.getName());
            assertEquals(s1.getNamespace(), s2.getNamespace());
            assertEquals(s1.getDoc(), s2.getDoc());

            if (s1.getType() == Schema.Type.RECORD) {
                java.util.List<Schema.Field> f1 = new java.util.ArrayList<>(s1.getFields());
                java.util.List<Schema.Field> f2 = new java.util.ArrayList<>(s2.getFields());
                assertEquals(f1.size(), f2.size());
                f1.sort(java.util.Comparator.comparing(Schema.Field::name));
                f2.sort(java.util.Comparator.comparing(Schema.Field::name));
                for (int i = 0; i < f1.size(); i++) {
                    Schema.Field field1 = f1.get(i);
                    Schema.Field field2 = f2.get(i);
                    assertEquals(field1.name(), field2.name());
                    assertEquals(field1.doc(), field2.doc());
                    assertEquals(field1.defaultVal(), field2.defaultVal());
                    assertEqual(field1.schema(), field2.schema());
                }
            } else if (s1.getType() == Schema.Type.ENUM) {
                assertEquals(s1.getEnumSymbols(), s2.getEnumSymbols());
            } else if (s1.getType() == Schema.Type.ARRAY) {
                assertEqual(s1.getElementType(), s2.getElementType());
            } else if (s1.getType() == Schema.Type.MAP) {
                assertEqual(s1.getValueType(), s2.getValueType());
            }
        }
    }

    new SchemaComparator().assertEqual(expected, actual);
  }
