      notificationsParam = notificationsParam.substring(0, ampIndex);
    }
    String decodedNotifications = URLDecoder.decode(notificationsParam, "UTF-8");

    Gson gson = new Gson();
    JsonElement element = gson.fromJson(decodedNotifications, JsonElement.class);
    JsonArray actualArray = element.getAsJsonArray();

    List<String> actualStrings = new ArrayList<>();
    for (JsonElement e : actualArray) {
      JsonObject obj = e.getAsJsonObject();
      String ns = obj.get("namespaceName").getAsString();
      long id = obj.get("notificationId").getAsLong();
      actualStrings.add(ns + "=" + id);
    }
    Collections.sort(actualStrings);

    List<String> expectedStrings = new ArrayList<>();
    expectedStrings.add(someNamespace + "=" + someNotificationId);
    expectedStrings.add(anotherNamespace + "=" + anotherNotificationId);
    Collections.sort(expectedStrings);

    assertEquals(expectedStrings, actualStrings);
  }
