//<fix start>
  @Test public void userSuppliedJaxbContext() throws Exception {
    JAXBContext context = JAXBContext.newInstance(Contact.class);
    JaxbConverterFactory factory = JaxbConverterFactory.create(context);
    Retrofit retrofit = new Retrofit.Builder()
        .baseUrl(server.url("/"))
        .addConverterFactory(factory)
        .build();
    service = retrofit.create(Service.class);

    server.enqueue(new MockResponse());

    Call<Void> call = service.postXml(SAMPLE_CONTACT);
    call.execute();

    RecordedRequest request = server.takeRequest();
    assertThat(request.getHeader("Content-Type")).isEqualTo("application/xml; charset=utf-8");

    String actualXml = request.getBody().readUtf8();

    javax.xml.parsers.DocumentBuilderFactory dbf = javax.xml.parsers.DocumentBuilderFactory.newInstance();
    javax.xml.parsers.DocumentBuilder db = dbf.newDocumentBuilder();

    org.w3c.dom.Document expectedDoc = db.parse(new org.xml.sax.InputSource(new java.io.StringReader(SAMPLE_CONTACT_XML)));
    org.w3c.dom.Document actualDoc = db.parse(new org.xml.sax.InputSource(new java.io.StringReader(actualXml)));

    java.util.List<String> expectedPaths = new java.util.ArrayList<>();
    java.util.List<String> actualPaths = new java.util.ArrayList<>();

    class PathExtractor {
      void extract(org.w3c.dom.Node node, String currentPath, java.util.List<String> paths) {
        if (node.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
          String nodeName = node.getNodeName();
          String newPath = currentPath + "/" + nodeName;

          if (node.getAttributes() != null) {
            for (int i = 0; i < node.getAttributes().getLength(); i++) {
              org.w3c.dom.Node attr = node.getAttributes().item(i);
              paths.add(newPath + "/@" + attr.getNodeName() + "=" + attr.getNodeValue());
            }
          }

          boolean hasElementChildren = false;
          org.w3c.dom.NodeList children = node.getChildNodes();
          for (int i = 0; i < children.getLength(); i++) {
            if (children.item(i).getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
              hasElementChildren = true;
              break;
            }
          }

          if (!hasElementChildren) {
            paths.add(newPath + "=" + node.getTextContent().trim());
          } else {
            for (int i = 0; i < children.getLength(); i++) {
              if (children.item(i).getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
                extract(children.item(i), newPath, paths);
              }
            }
          }
        }
      }
    }

    new PathExtractor().extract(expectedDoc.getDocumentElement(), "", expectedPaths);
    new PathExtractor().extract(actualDoc.getDocumentElement(), "", actualPaths);

    java.util.Collections.sort(expectedPaths);
    java.util.Collections.sort(actualPaths);

    assertThat(actualPaths).isEqualTo(expectedPaths);
  }
