    ReleaseMessage msg1 = latestReleaseMsgGroupByMsgContent.stream()
        .filter(m -> someMsgContent.equals(m.getMessage()))
        .findFirst()
        .orElse(null);
    ReleaseMessage msg2 = latestReleaseMsgGroupByMsgContent.stream()
        .filter(m -> anotherMsgContent.equals(m.getMessage()))
        .findFirst()
        .orElse(null);

    assertNotNull(msg1);
    assertNotNull(msg2);
    assertEquals(1, msg1.getId());
    assertEquals(someMsgContent, msg1.getMessage());
