    public void canFlushUnhandled() {
        Mockery localContext = new JUnit4Mockery();
        Consumer<AISMessage> localHandler = (Consumer<AISMessage>) localContext.mock(Consumer.class);
        NMEAMessageHandler localReceiver = new NMEAMessageHandler("TEST", localHandler);

        NMEAMessage unfragmentedNMEAMessage = NMEAMessage.fromString("!AIVDM,1,1,,B,15MqdBP000G@qoLEi69PVGaN0D0=,0*3A");
