            String[] arr = fields.split(",", -1);
            Arrays.sort(arr);
            return prefix + String.join(",", arr) + suffix;
        };

        assertEquals(expected, normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(expected, normalize.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(expected, normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(expected, normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
