    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };

        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        String actual = toString(wa);

        String expectedPrefix = getClassPrefix(wa) + "[" + BR;
        String expectedSuffix = BR + "]";

        assertTrue(actual.startsWith(expectedPrefix), "Actual string should start with expected prefix");
        assertTrue(actual.endsWith(expectedSuffix), "Actual string should end with expected suffix");

        String fieldsPart = actual.substring(expectedPrefix.length(), actual.length() - expectedSuffix.length());
        String expFieldsPart = exp.substring(expectedPrefix.length(), exp.length() - expectedSuffix.length());

        String brPattern = Pattern.quote(BR);
        Pattern fieldPattern = Pattern.compile("^  (boolArray|charArray|intArray|doubleArray|longArray|stringArray)=(.*?)(?=" + brPattern + "  (?:boolArray|charArray|intArray|doubleArray|longArray|stringArray)=|" + brPattern + "\\])", Pattern.MULTILINE | Pattern.DOTALL);

        Map<String, String> actualFields = new TreeMap<>();
        List<String> actualFieldNames = new ArrayList<>();
        Matcher m = fieldPattern.matcher(fieldsPart);
        while (m.find()) {
            String name = m.group(1);
            String value = m.group(2);
            if (value.endsWith(",")) {
                value = value.substring(0, value.length() - 1);
            }
            actualFieldNames.add(name);
            actualFields.put(name, value);
        }

        Map<String, String> expectedFieldsMap = new TreeMap<>();
        Matcher mExp = fieldPattern.matcher(expFieldsPart);
        while (mExp.find()) {
            String name = mExp.group(1);
            String value = mExp.group(2);
            if (value.endsWith(",")) {
                value = value.substring(0, value.length() - 1);
            }
            expectedFieldsMap.put(name, value);
        }

        assertEquals(expectedFieldsMap, actualFields);

        StringBuilder expectedFieldsPartReconstructed = new StringBuilder();
        for (int i = 0; i < actualFieldNames.size(); i++) {
            String name = actualFieldNames.get(i);
            expectedFieldsPartReconstructed.append("  ").append(name).append("=").append(actualFields.get(name));
            if (i < actualFieldNames.size() - 1) {
                expectedFieldsPartReconstructed.append(",").append(BR);
            }
        }
        assertEquals(expectedFieldsPartReconstructed.toString(), fieldsPart);
    }
