f3ee5eaa10c079131b0e077f.content:
The previous candidate fix weakened the test's ability to detect trailing field separators because Java's `String.split(",")` discards trailing empty strings by default. When a mutant left a trailing comma (e.g., `[...,instanceInt=67890,]`), the `split(",")` operation silently dropped the resulting empty string, causing the lists to match and the mutant to survive. 

To restore full deterministic predicate strength and kill the `removeLastFieldSeparator` / `appendEnd` mutants, we must use `split(",", -1)` to retain trailing empty strings, and explicitly assert that the string correctly terminates with `]`.

//<fix start>
    @Test
    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();

        String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class);
        String expected1 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
        assertEquals(expected1.substring(0, expected1.indexOf('[')), actual1.substring(0, actual1.indexOf('[')));
        assertTrue(actual1.endsWith("]"));
        List<String> exp1List = Arrays.asList(expected1.substring(expected1.indexOf('[') + 1, expected1.length() - 1).split(",", -1));
        Collections.sort(exp1List);
        List<String> act1List = Arrays.asList(actual1.substring(actual1.indexOf('[') + 1, actual1.length() - 1).split(",", -1));
        Collections.sort(act1List);
        assertEquals(exp1List, act1List);

        String actual2 = ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class);
        String expected2 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]";
        assertEquals(expected2.substring(0, expected2.indexOf('[')), actual2.substring(0, actual2.indexOf('[')));
        assertTrue(actual2.endsWith("]"));
        List<String> exp2List = Arrays.asList(expected2.substring(expected2.indexOf('[') + 1, expected2.length() - 1).split(",", -1));
        Collections.sort(exp2List);
        List<String> act2List = Arrays.asList(actual2.substring(actual2.indexOf('[') + 1, actual2.length() - 1).split(",", -1));
        Collections.sort(act2List);
        assertEquals(exp2List, act2List);

        String actual3 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        String expected3 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
        assertEquals(expected3.substring(0, expected3.indexOf('[')), actual3.substring(0, actual3.indexOf('[')));
        assertTrue(actual3.endsWith("]"));
        List<String> exp3List = Arrays.asList(expected3.substring(expected3.indexOf('[') + 1, expected3.length() - 1).split(",", -1));
        Collections.sort(exp3List);
        List<String> act3List = Arrays.asList(actual3.substring(actual3.indexOf('[') + 1, actual3.length() - 1).split(",", -1));
        Collections.sort(act3List);
        assertEquals(exp3List, act3List);

        String actual4 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        String expected4 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
        assertEquals(expected4.substring(0, expected4.indexOf('[')), actual4.substring(0, actual4.indexOf('[')));
        assertTrue(actual4.endsWith("]"));
        List<String> exp4List = Arrays.asList(expected4.substring(expected4.indexOf('[') + 1, expected4.length() - 1).split(",", -1));
        Collections.sort(exp4List);
        List<String> act4List = Arrays.asList(actual4.substring(actual4.indexOf('[') + 1, actual4.length() - 1).split(",", -1));
        Collections.sort(act4List);
        assertEquals(exp4List, act4List);
    }
