        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        Function<String, String> prefix = s -> s.substring(0, s.indexOf('[') + 1);
        Function<String, Map<String, String>> parse = s -> {
            int start = s.indexOf('[');
            int end = s.lastIndexOf(']');
            String fields = s.substring(start + 1, end);
            Map<String, String> map = new HashMap<>();
            if (!fields.isEmpty()) {
                for (String pair : fields.split(",")) {
                    int eqIdx = pair.indexOf('=');
                    map.put(pair.substring(0, eqIdx), pair.substring(eqIdx + 1));
                }
            }
            return map;
        };

        Map<String, String> expected1 = new HashMap<>();
        expected1.put("staticString2", "staticString2");
        expected1.put("staticInt2", "67890");

        Map<String, String> expected2 = new HashMap<>();
        expected2.put("staticString2", "staticString2");
        expected2.put("staticInt2", "67890");
        expected2.put("staticString", "staticString");
        expected2.put("staticInt", "12345");

        String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class);
        assertEquals(
            new AbstractMap.SimpleImmutableEntry<>(this.toBaseString(instance1) + "[", expected1),
            new AbstractMap.SimpleImmutableEntry<>(prefix.apply(actual1), parse.apply(actual1)));

        String actual2 = ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class);
