    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);
        int[] v = {1, 2, 3};

        Set<Integer> validAll = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == j) continue;
                for (int k = 0; k < 3; k++) {
                    if (k == i || k == j) continue;
                    validAll.add(((17 * 37 + v[i]) * 37 + v[j]) * 37 + v[k]);
                }
            }
        }

        Set<Integer> validExcludeTwo = new HashSet<>();
        for (int i : new int[]{0, 2}) {
            for (int j : new int[]{0, 2}) {
                if (i == j) continue;
                validExcludeTwo.add((17 * 37 + v[i]) * 37 + v[j]);
            }
        }

        Set<Integer> validExcludeThree = new HashSet<>();
        for (int i : new int[]{0, 1}) {
            for (int j : new int[]{0, 1}) {
                if (i == j) continue;
                validExcludeThree.add((17 * 37 + v[i]) * 37 + v[j]);
            }
        }

        Set<Integer> validExcludeTwoThree = new HashSet<>();
        validExcludeTwoThree.add(17 * 37 + v[0]);

        Set<Integer> validExcludeAll = new HashSet<>();
        validExcludeAll.add(17);

        assertTrue(validAll.contains(HashCodeBuilder.reflectionHashCode(x)));

        assertTrue(validAll.contains(HashCodeBuilder.reflectionHashCode(x, (String[]) null)));
        assertTrue(validAll.contains(HashCodeBuilder.reflectionHashCode(x)));
        assertTrue(validAll.contains(HashCodeBuilder.reflectionHashCode(x, "xxx")));

        assertTrue(validExcludeTwo.contains(HashCodeBuilder.reflectionHashCode(x, "two")));
        assertTrue(validExcludeThree.contains(HashCodeBuilder.reflectionHashCode(x, "three")));

        assertTrue(validExcludeTwoThree.contains(HashCodeBuilder.reflectionHashCode(x, "two", "three")));

        assertTrue(validExcludeAll.contains(HashCodeBuilder.reflectionHashCode(x, "one", "two", "three")));
        assertTrue(validExcludeAll.contains(HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx")));
    }
