    @Test
    public void testReflectionHashCodeExcludeFields() throws Exception {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        int expected = 17;
        for (Field f : x.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            expected = expected * 37 + f.getInt(x);
        }
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x, "xxx"));

        expected = 17;
        for (Field f : x.getClass().getDeclaredFields()) {
            if (f.getName().equals("two")) continue;
            f.setAccessible(true);
            expected = expected * 37 + f.getInt(x);
        }
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x, "two"));

        expected = 17;
        for (Field f : x.getClass().getDeclaredFields()) {
            if (f.getName().equals("three")) continue;
            f.setAccessible(true);
            expected = expected * 37 + f.getInt(x);
        }
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x, "three"));

        expected = 17;
        for (Field f : x.getClass().getDeclaredFields()) {
            if (f.getName().equals("two") || f.getName().equals("three")) continue;
            f.setAccessible(true);
            expected = expected * 37 + f.getInt(x);
        }
        assertEquals(expected, HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }
