    class FieldSorter {
      @SuppressWarnings("unchecked")
      void sort(Object obj) {
        if (obj instanceof Map) {
          Map<String, Object> map = (Map<String, Object>) obj;
          if (map.containsKey("fields")) {
            List<Map<String, Object>> fields = (List<Map<String, Object>>) map.get("fields");
            fields.sort(Comparator.comparing(f -> (String) f.get("name")));
            for (Map<String, Object> field : fields) {
              sort(field.get("type"));
            }
          }
        } else if (obj instanceof List) {
          for (Object item : (List<?>) obj) {
            sort(item);
          }
        }
      }
    }

    new FieldSorter().sort(expectedMap);
    new FieldSorter().sort(actualMap);

    assertEquals(expectedMap, actualMap);
  }
