    java.util.List<com.fasterxml.jackson.databind.JsonNode> expFields = new java.util.ArrayList<>();
    expectedNode.get("fields").elements().forEachRemaining(expFields::add);
    expFields.sort(cmp);
    ((com.fasterxml.jackson.databind.node.ArrayNode) expectedNode.get("fields")).removeAll();
    expFields.forEach(((com.fasterxml.jackson.databind.node.ArrayNode) expectedNode.get("fields"))::add);

    java.util.List<com.fasterxml.jackson.databind.JsonNode> actFields = new java.util.ArrayList<>();
    actualNode.get("fields").elements().forEachRemaining(actFields::add);
    actFields.sort(cmp);
    ((com.fasterxml.jackson.databind.node.ArrayNode) actualNode.get("fields")).removeAll();
    actFields.forEach(((com.fasterxml.jackson.databind.node.ArrayNode) actualNode.get("fields"))::add);

    for (com.fasterxml.jackson.databind.JsonNode n : expFields) {
      if (n.has("fields") && n.get("fields").isArray()) {
        java.util.List<com.fasterxml.jackson.databind.JsonNode> nested = new java.util.ArrayList<>();
        n.get("fields").elements().forEachRemaining(nested::add);
        nested.sort(cmp);
        ((com.fasterxml.jackson.databind.node.ArrayNode) n.get("fields")).removeAll();
        nested.forEach(((com.fasterxml.jackson.databind.node.ArrayNode) n.get("fields"))::add);
      }
    }
    for (com.fasterxml.jackson.databind.JsonNode n : actFields) {
      if (n.has("fields") && n.get("fields").isArray()) {
        java.util.List<com.fasterxml.jackson.databind.JsonNode> nested = new java.util.ArrayList<>();
        n.get("fields").elements().forEachRemaining(nested::add);
        nested.sort(cmp);
        ((com.fasterxml.jackson.databind.node.ArrayNode) n.get("fields")).removeAll();
        nested.forEach(((com.fasterxml.jackson.databind.node.ArrayNode) n.get("fields"))::add);
      }
    }

    assertEquals(expectedNode, actualNode);
  }
