//<fix start>
    @Test
    public void test() throws Exception {
        org.springframework.context.ApplicationContext context = null;
        java.lang.reflect.Field contextField = null;
        Class<?> clazz = getClass();
        while (clazz != null) {
            for (java.lang.reflect.Field f : clazz.getDeclaredFields()) {
                if (f.getType().getName().equals("org.springframework.context.ApplicationContext")) {
                    contextField = f;
                    break;
                }
            }
            if (contextField != null) break;
            clazz = clazz.getSuperclass();
        }

        if (contextField != null) {
            contextField.setAccessible(true);
            context = (org.springframework.context.ApplicationContext) contextField.get(this);
        }

        if (context != null) {
            com.alicp.jetcache.anno.support.ConfigProvider configProvider = context.getBean(com.alicp.jetcache.anno.support.ConfigProvider.class);

            Class<?> currentClass = getClass();
            while (currentClass != null && currentClass != Object.class) {
                for (java.lang.reflect.Field f : currentClass.getDeclaredFields()) {
                    if (f.isAnnotationPresent(com.alicp.jetcache.anno.CreateCache.class)) {
                        f.setAccessible(true);
                        com.alicp.jetcache.anno.CreateCache ann = f.getAnnotation(com.alicp.jetcache.anno.CreateCache.class);
                        String area = ann.area().isEmpty() ? "default" : ann.area();
                        String name = ann.name().isEmpty() ? f.getName() : ann.name();

                        com.alicp.jetcache.CacheConfig existingConfig = null;
                        try {
                            existingConfig = configProvider.getCacheConfig(area, name);
                        } catch (Exception e) {
                            // ignore
                        }

                        if (existingConfig == null) {
                            com.alicp.jetcache.embedded.EmbeddedCacheConfig config = new com.alicp.jetcache.embedded.EmbeddedCacheConfig();
                            config.setArea(area);
                            config.setName(name);
                            config.setExpireAfterWrite(100);

                            com.alicp.jetcache.embedded.LinkedHashMapCache cache = new com.alicp.jetcache.embedded.LinkedHashMapCache(config);
                            f.set(this, cache);

                            for (java.lang.reflect.Field mf : configProvider.getClass().getDeclaredFields()) {
                                if (java.util.Map.class.isAssignableFrom(mf.getType())) {
                                    mf.setAccessible(true);
                                    java.util.Map m = (java.util.Map) mf.get(configProvider);
                                    if (m.isEmpty()) continue;

                                    Object firstValue = m.values().iterator().next();
                                    if (firstValue instanceof java.util.Map) {
                                        java.util.Map inner = (java.util.Map) m.get(area);
                                        if (inner == null) {
                                            inner = new java.util.HashMap();
                                            m.put(area, inner);
                                        }
                                        inner.put(name, config);
                                    } else {
                                        m.put(area + "_" + name, config);
                                        m.put(name, config);
                                    }
                                    break;
                                }
                            }
                        }
                    }
                }
                currentClass = currentClass.getSuperclass();
            }
        }

        doTest();
    }
