    @Test
    public void transport_chunking() throws Exception {
        // Reset polluted system properties
        java.util.Enumeration<?> e = System.getProperties().propertyNames();
        while (e.hasMoreElements()) {
            String key = (String) e.nextElement();
            if (key.contains("ClassFilter") || key.contains("remoting")) {
                System.clearProperty(key);
            }
        }

        // Reset polluted static caches in ClassFilter and DefaultClassFilter
        for (String className : new String[]{"hudson.remoting.ClassFilter", "hudson.remoting.DefaultClassFilter"}) {
            try {
                Class<?> clazz = Class.forName(className);
                for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
                    if (java.lang.reflect.Modifier.isStatic(field.getModifiers()) && !field.getType().isPrimitive()) {
                        field.setAccessible(true);
                        if (java.lang.reflect.Modifier.isFinal(field.getModifiers())) {
                            try {
                                java.lang.reflect.Field modifiersField = java.lang.reflect.Field.class.getDeclaredField("modifiers");
                                modifiersField.setAccessible(true);
                                modifiersField.setInt(field, field.getModifiers() & ~java.lang.reflect.Modifier.FINAL);
                            } catch (Exception ex) {
                                // Ignore if modifiers field is not accessible (e.g., Java 12+)
                            }
                        }
                        field.set(null, null);
                    }
                }
            } catch (Exception ex) {
                // Ignore if class is not found
            }
        }

        setUp();
        commandStreamTestSequence();
    }
