//<fix start>
    @Test
    public void testEquals2Annotations()
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        java.util.function.Function<String, String> normalize = s -> {
            int start = s.indexOf("qualifiers=[");
            if (start == -1) return s;
            int end = s.indexOf("]", start);
            if (end == -1) return s;
            String prefix = s.substring(0, start + "qualifiers=[".length());
            String suffix = s.substring(end);
            String qualifiersStr = s.substring(start + "qualifiers=[".length(), end);
            if (qualifiersStr.isEmpty()) {
                return prefix + suffix;
            }
            String[] qualifiers = qualifiersStr.split(", (?=@)");
            java.util.Arrays.sort(qualifiers);
            return prefix + String.join(", ", qualifiers) + suffix;
        };

        Assert.assertEquals(normalize.apply(a.toString()), normalize.apply(b.toString()));
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
