        Object qa = f.get(a);
        if (qa instanceof Annotation[]) {
            java.util.Arrays.sort((Annotation[]) qa, (x, y) -> x.toString().compareTo(y.toString()));
        } else if (qa instanceof java.util.List) {
            java.util.Collections.sort((java.util.List<Annotation>) qa, (x, y) -> x.toString().compareTo(y.toString()));
        } else if (qa instanceof java.util.Set) {
            java.util.Set<Annotation> sortedSet = new java.util.TreeSet<>((x, y) -> x.toString().compareTo(y.toString()));
            sortedSet.addAll((java.util.Set<Annotation>) qa);
            f.set(a, sortedSet);
        }

        Object qb = f.get(b);
        if (qb instanceof Annotation[]) {
            java.util.Arrays.sort((Annotation[]) qb, (x, y) -> x.toString().compareTo(y.toString()));
        } else if (qb instanceof java.util.List) {
            java.util.Collections.sort((java.util.List<Annotation>) qb, (x, y) -> x.toString().compareTo(y.toString()));
        } else if (qb instanceof java.util.Set) {
