def test_core_commands():
    # Clean up polluted state from previous tests
    for obj in [Breathe, engine, getattr(engine, 'compiler', None)]:
        if obj is None:
            continue
        for attr in ['_contexts', 'contexts', '_rules', 'rules', '_global_context', '_enabled_contexts', 'enabled_contexts']:
            if hasattr(obj, attr):
                val = getattr(obj, attr)
                if isinstance(val, (dict, list, set)):
                    val.clear()
                elif hasattr(val, 'rules') and isinstance(val.rules, (dict, list, set)):
                    val.rules.clear()

    Breathe.add_commands(
        None,
