Looking at the failure, the polluter's `log.set_default_format()` changes a formatter that my Round 1 fix didn't reach - it only reset handlers on the root and test loggers, but the `logx` module's stdout handler lives on a different logger or directly on the `log` object. I need a comprehensive reset that checks ALL loggers, ALL handlers on the `log` object itself, and any format-related attributes.

#<victim start>
def test_plain_output(caplog, capsys):
    import logging

    # Reset logx format to plain to counteract polluter's set_default_format()
    pf = logging.Formatter('%(message)s')

    # 1. Try known API methods
    for mn in ['set_plain_format', 'reset_format', 'set_plain', 'plain_format']:
        if hasattr(log, mn):
            getattr(log, mn)()
    if hasattr(log, 'set_format'):
        log.set_format('%(message)s')

    # 2. Modify format-related attributes directly on the log object
    for a in ['_format', 'format', '_fmt', 'fmt', '_formatter', 'formatter',
              'output_format', 'log_format', 'default_format', '_default_format']:
        if hasattr(log, a):
            v = getattr(log, a)
            if isinstance(v, str):
                setattr(log, a, '%(message)s')
            elif isinstance(v, logging.Formatter):
                setattr(log, a, pf)

    # 3. Reset formatters on any Handler/Logger attributes of the log object
    for a in dir(log):
        try:
            o = getattr(log, a)
            if isinstance(o, logging.Handler):
                o.setFormatter(pf)
            elif isinstance(o, logging.Logger):
                for h in o.handlers:
                    h.setFormatter(pf)
        except Exception:
            pass

    # 4. Reset formatters on ALL handlers across ALL existing loggers
    for n in list(logging.Logger.manager.loggerDict.keys()) + ['']:
        for h in logging.getLogger(n).handlers:
            h.setFormatter(pf)

    # Original test assertions
    logger_name = log.current_logger_name()
    assert logger_name == "tests.test_logx"
    FIRST_MESSAGE = "first message"
    log.info(FIRST_MESSAGE)
    assert m(caplog) == FIRST_MESSAGE
    out, err = capsys.readouterr()
    assert out == FIRST_MESSAGE + "\n"
    assert not err
#<victim end>

#<polluter start>
def test_formatted_output(caplog, capsys):
    import logging

    log.set_default_format()
    try:
        log.debug("debug")
        assert m(caplog) == "debug"
        out, err = capsys.readouterr()
        assert out.endswith("debug\n")
        assert "DEBUG [tests.test_logx.test_formatted_output:" in out
        assert not err
    finally:
        # Teardown: reset logx format back to plain
        pf = logging.Formatter('%(message)s')
        for mn in ['set_plain_format', 'reset_format', 'set_plain', 'plain_format']:
            if hasattr(log, mn):
                getattr(log, mn)()
        if hasattr(log, 'set_format'):
            log.set_format('%(message)s')
        for a in ['_format', 'format', '_fmt', 'fmt', '_formatter', 'formatter',
                  'output_format', 'log_format', 'default_format', '_default_format']:
            if hasattr(log, a):
                v = getattr(log, a)
                if isinstance(v, str):
                    setattr(log, a, '%(message)s')
                elif isinstance(v, logging.Formatter):
                    setattr(log, a, pf)
        for a in dir(log):
            try:
                o = getattr(log, a)
                if isinstance(o, logging.Handler):
                    o.setFormatter(pf)
                elif isinstance(o, logging.Logger):
                    for h in o.handlers:
                        h.setFormatter(pf)
            except Exception:
                pass
        for n in list(logging.Logger.manager.loggerDict.keys()) + ['']:
            for h in logging.getLogger(n).handlers:
                h.setFormatter(pf)
