    @Test
    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String expectedPrefix = this.toBaseString(instance1);

        Map<String, String> expectedMap = new HashMap<>();
        expectedMap.put("staticString", "staticString");
        expectedMap.put("staticInt", "12345");

        Function<String, Map<String, String>> parseFields = actual -> {
            int start = actual.indexOf('[');
            int end = actual.lastIndexOf(']');
            Map<String, String> map = new HashMap<>();
            if (start != -1 && end != -1 && start < end) {
                String fieldsStr = actual.substring(start + 1, end);
                if (!fieldsStr.isEmpty()) {
                    for (String pair : fieldsStr.split(",")) {
                        int eqIdx = pair.indexOf('=');
                        if (eqIdx != -1) {
                            map.put(pair.substring(0, eqIdx), pair.substring(eqIdx + 1));
                        }
                    }
                }
            }
            return map;
        };

        String[] actuals = {
            ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class),
            ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class),
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class),
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)
        };

        for (String actual : actuals) {
            int start = actual.indexOf('[');
            int end = actual.lastIndexOf(']');
            assertEquals(expectedPrefix + "[", actual.substring(0, start + 1));
            assertEquals("]", actual.substring(end));
            assertEquals(expectedMap, parseFields.apply(actual));
        }
    }
