    @Test
    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();

        java.util.function.UnaryOperator<String> normalize = s -> {
            int start = s.indexOf('[');
            int end = s.lastIndexOf(']');
            if (start == -1 || end == -1 || start >= end) {
                return s;
            }
            String prefix = s.substring(0, start + 1);
            String suffix = s.substring(end);
            String fields = s.substring(start + 1, end);
            if (fields.isEmpty()) {
                return prefix + suffix;
            }
