    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        String actual = toString(wa);

        java.util.function.Function<String, String> sortFields = s -> {
            int start = s.indexOf('[');
            int end = s.lastIndexOf(']');
            if (start == -1 || end == -1) return s;
            String prefix = s.substring(0, start + 1);
            String suffix = s.substring(end);
            String body = s.substring(start + 1, end);

            String br2 = java.util.regex.Pattern.quote(BR) + "  ";
            java.util.regex.Pattern p = java.util.regex.Pattern.compile(br2 + "[a-zA-Z0-9_]+=.*?(?=" + br2 + "[a-zA-Z0-9_]+=|\\z)", java.util.regex.Pattern.DOTALL);
            java.util.regex.Matcher m = p.matcher(body);
            List<String> fields = new ArrayList<>();
            while (m.find()) {
                fields.add(m.group());
            }
            java.util.Collections.sort(fields);

            StringBuilder sb = new StringBuilder();
            for (String f : fields) {
                sb.append(f);
            }
            return prefix + sb.toString() + suffix;
        };

        assertEquals(sortFields.apply(exp), sortFields.apply(actual));
    }
