    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();
        assertEquals(
            sortFields(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            sortFields(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            sortFields(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            sortFields(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            sortFields(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            sortFields(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            sortFields(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            sortFields(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }

    private String sortFields(String str) {
        if (str == null) {
            return null;
        }
        int start = str.indexOf('[');
        int end = str.lastIndexOf(']');
        if (start == -1 || end == -1 || start >= end) {
            return str;
        }
        String prefix = str.substring(0, start + 1);
        String suffix = str.substring(end);
        String fieldsStr = str.substring(start + 1, end);
        if (fieldsStr.isEmpty()) {
            return prefix + suffix;
        }
        String[] fields = fieldsStr.split(",");
        java.util.Arrays.sort(fields);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < fields.length; i++) {
            if (i > 0) {
                sb.append(",");
            }
            sb.append(fields[i]);
        }
        return prefix + sb.toString() + suffix;
    }
