    @Test
    public void testReflectionHierarchy() {
        java.util.function.UnaryOperator<String> sortFields = str -> {
            int start = str.indexOf('[');
            int end = str.lastIndexOf(']');
            if (start < 0 || end < 0 || start >= end) {
                return str;
            }
            String prefix = str.substring(0, start + 1);
            String suffix = str.substring(end);
            String fieldsStr = str.substring(start + 1, end);
            if (fieldsStr.isEmpty()) {
                return prefix + suffix;
            }
            String[] parts = fieldsStr.split(",");
            java.util.Arrays.sort(parts);
            return prefix + String.join(",", parts) + suffix;
        };

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);
        assertEquals(sortFields.apply(baseString + "[a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA)));
        assertEquals(sortFields.apply(baseString + "[a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA, null)));
        assertEquals(sortFields.apply(baseString + "[a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA, null, false)));
        assertEquals(sortFields.apply(baseString + "[a=a,transientA=t]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA, null, true)));
        assertEquals(sortFields.apply(baseString + "[a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA, null, false, null)));
        assertEquals(sortFields.apply(baseString + "[a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA, null, false, Object.class)));
        assertEquals(sortFields.apply(baseString + "[a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class)));

        final ReflectionTestFixtureB baseB = new ReflectionTestFixtureB();
