        assertEquals(sortFields.apply(baseString + "[b=b,a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseB, null)));
        assertEquals(sortFields.apply(baseString + "[b=b,a=a]"), sortFields.apply(ToStringBuilder.reflectionToString(baseB, null, false)));
