//<fix start>
  @Test
  public void testAvroDoc() throws Exception {
    String expectedJson = "{\"type\":\"record\",\"name\":\"DocTest\",\"namespace\":\"org.apache.avro.reflect.TestReflect\","
        + "\"doc\":\"DocTest class docs\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"doc\":\"Some Documentation\"},"
        + "{\"name\":\"enums\",\"type\":{\"type\":\"enum\",\"name\":\"DocTestEnum\","
        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    String actualJson = ReflectData.get().getSchema(DocTest.class).toString();

    ObjectMapper mapper = new ObjectMapper();
    JsonNode expectedNode = mapper.readTree(expectedJson);
    JsonNode actualNode = mapper.readTree(actualJson);

    java.util.function.Consumer<JsonNode> sortFields = new java.util.function.Consumer<JsonNode>() {
      @Override
      public void accept(JsonNode node) {
        if (node.isObject()) {
          if (node.has("fields") && node.get("fields").isArray()) {
            ArrayNode fields = (ArrayNode) node.get("fields");
            java.util.List<JsonNode> list = new java.util.ArrayList<>();
            fields.forEach(list::add);
            list.sort(java.util.Comparator.comparing(n -> n.get("name").asText()));
            ArrayNode sortedFields = mapper.createArrayNode();
            for (JsonNode n : list) {
              this.accept(n);
              sortedFields.add(n);
            }
            ((ObjectNode) node).set("fields", sortedFields);
          }
          node.forEach(this::accept);
        } else if (node.isArray()) {
          node.forEach(this::accept);
        }
      }
    };

    sortFields.accept(expectedNode);
    sortFields.accept(actualNode);

    assertEquals(expectedNode, actualNode);
  }
//<fix end>

