    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIf = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        List<String> expectedIfs = new ArrayList<>();
        int start = 0;
        while (true) {
            int ifStart = expectedWhereAllIf.indexOf("<if", start);
            if (ifStart == -1) break;
            int ifEnd = expectedWhereAllIf.indexOf("</if>", ifStart);
            if (ifEnd == -1) break;
            expectedIfs.add(expectedWhereAllIf.substring(ifStart, ifEnd + 5));
            start = ifEnd + 5;
        }
        Collections.sort(expectedIfs);

        List<String> actualIfs = new ArrayList<>();
        start = 0;
        while (true) {
            int ifStart = whereAllIfColumns.indexOf("<if", start);
            if (ifStart == -1) break;
            int ifEnd = whereAllIfColumns.indexOf("</if>", ifStart);
            if (ifEnd == -1) break;
            actualIfs.add(whereAllIfColumns.substring(ifStart, ifEnd + 5));
            start = ifEnd + 5;
        }
        Collections.sort(actualIfs);

        Assert.assertEquals(expectedIfs, actualIfs);
        int firstIf = whereAllIfColumns.indexOf("<if");
        int lastIfEnd = whereAllIfColumns.lastIndexOf("</if>") + 5;
        Assert.assertTrue(firstIf != -1);
        Assert.assertEquals("<where>", whereAllIfColumns.substring(0, firstIf));
        Assert.assertEquals(" AND is_valid = 1</where>", whereAllIfColumns.substring(lastIfEnd));

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String expectedUpdateSet = "<set>username = #{username},is_valid = 1,</set>";
        String expectedContent = expectedUpdateSet.substring(5, expectedUpdateSet.length() - 6);
        List<String> expectedSets = new ArrayList<>();
        for (String part : expectedContent.split(",")) {
            if (!part.isEmpty()) expectedSets.add(part);
        }
        Collections.sort(expectedSets);

        String actualContent = updateSetColumns.substring(5, updateSetColumns.length() - 6);
        List<String> actualSets = new ArrayList<>();
        for (String part : actualContent.split(",")) {
            if (!part.isEmpty()) actualSets.add(part);
        }
        Collections.sort(actualSets);

        Assert.assertEquals(expectedSets, actualSets);
        Assert.assertTrue(updateSetColumns.startsWith("<set>"));
        Assert.assertTrue(updateSetColumns.endsWith("</set>"));
    }
