    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        List<String> ifs = new ArrayList<String>();
        int idx = 0;
        while (true) {
            int start = whereAllIfColumns.indexOf("<if", idx);
            if (start == -1) break;
            int end = whereAllIfColumns.indexOf("</if>", start);
            if (end == -1) break;
            ifs.add(whereAllIfColumns.substring(start, end + 5));
            idx = end + 5;
        }
        Collections.sort(ifs);

        String remaining = whereAllIfColumns;
        for (String ifTag : ifs) {
            remaining = remaining.replace(ifTag, "");
        }

        Assert.assertEquals("<where> AND is_valid = 1</where>", remaining);
        Assert.assertEquals(2, ifs.size());
        Assert.assertEquals("<if test=\"id != null\"> AND id = #{id}</if>", ifs.get(0));
        Assert.assertEquals("<if test=\"username != null\"> AND username = #{username}</if>", ifs.get(1));

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertTrue(updateSetColumns.startsWith("<set>"));
        Assert.assertTrue(updateSetColumns.endsWith("</set>"));
        String content = updateSetColumns.substring(5, updateSetColumns.length() - 6);
        String[] parts = content.split(",");
        Assert.assertEquals(3, parts.length);
        Assert.assertTrue(parts[2].isEmpty());
        List<String> nonEmpty = new ArrayList<String>();
        nonEmpty.add(parts[0]);
        nonEmpty.add(parts[1]);
        Collections.sort(nonEmpty);
        Assert.assertEquals("is_valid = 1", nonEmpty.get(0));
        Assert.assertEquals("username = #{username}", nonEmpty.get(1));
    }
//<fix end>

