    @Test
    public void userRequest() throws Exception {
        // Reset polluted system properties
        for (String key : new java.util.HashSet<>(System.getProperties().stringPropertyNames())) {
            if (key.contains("ClassFilter") || key.contains("Override")) {
                System.clearProperty(key);
            }
        }

        // Reset static cache in ClassFilter and its inner classes
        java.util.List<Class<?>> classesToCheck = new java.util.ArrayList<>();
        classesToCheck.add(hudson.remoting.ClassFilter.class);
        classesToCheck.addAll(java.util.Arrays.asList(hudson.remoting.ClassFilter.class.getDeclaredClasses()));

        for (Class<?> clazz : classesToCheck) {
            for (java.lang.reflect.Field f : clazz.getDeclaredFields()) {
                if (java.lang.reflect.Modifier.isStatic(f.getModifiers())) {
                    f.setAccessible(true);
                    try {
                        java.lang.reflect.Field mod = java.lang.reflect.Field.class.getDeclaredField("modifiers");
                        mod.setAccessible(true);
                        mod.setInt(f, f.getModifiers() & ~java.lang.reflect.Modifier.FINAL);
                    } catch (Exception e) {
                        // ignore
                    }
                    try {
                        if (f.getType().isAssignableFrom(hudson.remoting.ClassFilter.class)) {
                            f.set(null, hudson.remoting.ClassFilter.createDefaultInstance());
                        } else if (f.getType() == java.util.concurrent.atomic.AtomicReference.class) {
                            Object val = f.get(null);
                            if (val != null) {
                                ((java.util.concurrent.atomic.AtomicReference<Object>) val).set(hudson.remoting.ClassFilter.createDefaultInstance());
                            }
                        }
                    } catch (Exception e) {
                        // ignore
                    }
                }
            }
        }

        setUp();
        userRequestTestSequence();
