                   + "]";
        String actual = toString(wa);
        String[] actualLines = actual.split("\\R");
        String[] expLines = exp.split("\\R");

        assertEquals(expLines.length, actualLines.length);
        assertEquals(expLines[0], actualLines[0]);
        assertEquals(expLines[expLines.length - 1], actualLines[actualLines.length - 1]);

        List<String> actualFields = new ArrayList<>();
        for (int i = 1; i < actualLines.length - 1; i++) {
            String line = actualLines[i];
            if (line.endsWith(",")) {
                line = line.substring(0, line.length() - 1);
            }
            actualFields.add(line);
        }
        Collections.sort(actualFields);

        List<String> expFields = new ArrayList<>();
        for (int i = 1; i < expLines.length - 1; i++) {
            String line = expLines[i];
            if (line.endsWith(",")) {
                line = line.substring(0, line.length() - 1);
            }
            expFields.add(line);
        }
        Collections.sort(expFields);

        assertEquals(expFields, actualFields);
