            java.lang.reflect.Field unsafeField = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
            unsafeField.setAccessible(true);
            sun.misc.Unsafe unsafe = (sun.misc.Unsafe) unsafeField.get(null);
            for (java.lang.reflect.Field field : ClassFilter.class.getDeclaredFields()) {
                if (java.lang.reflect.Modifier.isStatic(field.getModifiers())) {
                    if (field.getType() == ClassFilter.class) {
                        unsafe.putObject(unsafe.staticFieldBase(field), unsafe.staticFieldOffset(field), null);
                    } else if (field.getType() == java.util.concurrent.atomic.AtomicReference.class) {
                        field.setAccessible(true);
                        Object val = field.get(null);
                        if (val instanceof java.util.concurrent.atomic.AtomicReference) {
                            ((java.util.concurrent.atomic.AtomicReference<?>) val).set(null);
                        }
                    }
                }
            }
        } catch (Throwable t) {
            // Fallback or ignore if Unsafe is not available
        }
        setUp();
        userRequestTestSequence();
    }
