	@Test
	public void testImport() throws Exception {
		ClassPathResource resource = new ClassPathResource("importing.xsd", getClass());
		CommonsXsdSchemaCollection schemaCollection = new CommonsXsdSchemaCollection(resource);
		schemaCollection.setInline(true);
		schemaCollection.afterPropertiesSet();
		definition.setSchemaCollection(schemaCollection);

		definition.setPortTypeName("Order");
		definition.setTargetNamespace("http://www.springframework.org/spring-ws/import/definitions");
		definition.setLocationUri("http://localhost:8080/");
		definition.afterPropertiesSet();

		DOMResult domResult = new DOMResult();
		transformer.transform(definition.getSource(), domResult);

		Document result = (Document) domResult.getNode();
		Document expected = documentBuilder.parse(getClass().getResourceAsStream("import-inline.wsdl"));

		class NodeSorter {
			void sort(org.w3c.dom.Node node) {
				if (node == null) return;
				java.util.List<org.w3c.dom.Node> allChildren = new java.util.ArrayList<>();
				org.w3c.dom.NodeList nodeList = node.getChildNodes();
				for (int i = 0; i < nodeList.getLength(); i++) {
					allChildren.add(nodeList.item(i));
				}

				java.util.List<org.w3c.dom.Node> elements = new java.util.ArrayList<>();
				for (org.w3c.dom.Node child : allChildren) {
					if (child.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
						elements.add(child);
						sort(child);
					}
				}

				elements.sort((n1, n2) -> {
					int cmp = n1.getNodeName().compareTo(n2.getNodeName());
					if (cmp != 0) return cmp;
					if (n1 instanceof org.w3c.dom.Element && n2 instanceof org.w3c.dom.Element) {
						String attr1 = ((org.w3c.dom.Element) n1).getAttribute("name");
						String attr2 = ((org.w3c.dom.Element) n2).getAttribute("name");
						return attr1.compareTo(attr2);
					}
					return 0;
				});

				int elemIdx = 0;
				for (int i = 0; i < allChildren.size(); i++) {
					if (allChildren.get(i).getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
						allChildren.set(i, elements.get(elemIdx++));
					}
				}

				while (node.hasChildNodes()) {
					node.removeChild(node.getFirstChild());
				}
				for (org.w3c.dom.Node child : allChildren) {
					node.appendChild(child);
				}
			}
		}

		new NodeSorter().sort(expected.getDocumentElement());
		new NodeSorter().sort(result.getDocumentElement());

		assertXMLEqual("Invalid WSDL built", expected, result);
	}
