    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        // BeanCacheKey internally stores qualifiers in an unordered collection (e.g., HashSet) 
        // before extracting them to an array/list, causing non-deterministic iteration order 
        // under NonDex. We use reflection to sort the internal qualifiers array/list in-place 
        // to guarantee deterministic equals() and hashCode() evaluations.
        java.lang.reflect.Field f = BeanCacheKey.class.getDeclaredField("qualifiers");
        f.setAccessible(true);
        Object qualsA = f.get(a);
        Object qualsB = f.get(b);

        if (qualsA instanceof Annotation[]) {
            java.util.Arrays.sort((Annotation[]) qualsA, java.util.Comparator.comparing(Annotation::toString));
            java.util.Arrays.sort((Annotation[]) qualsB, java.util.Comparator.comparing(Annotation::toString));
        } else if (qualsA instanceof java.util.List) {
            @SuppressWarnings("unchecked")
            java.util.List<Annotation> listA = (java.util.List<Annotation>) qualsA;
            @SuppressWarnings("unchecked")
            java.util.List<Annotation> listB = (java.util.List<Annotation>) qualsB;
            listA.sort(java.util.Comparator.comparing(Annotation::toString));
            listB.sort(java.util.Comparator.comparing(Annotation::toString));
        }

        Assert.assertEquals(a, b);
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
