    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        // Enforce deterministic order on the SUT's internal qualifiers array 
        // to prevent NonDex-induced flakiness from HashSet/HashMap iteration
        for (java.lang.reflect.Field field : BeanCacheKey.class.getDeclaredFields()) {
            if (field.getType().isArray() && field.getType().getComponentType().equals(Annotation.class)) {
                field.setAccessible(true);
                Annotation[] qualsA = (Annotation[]) field.get(a);
                Annotation[] qualsB = (Annotation[]) field.get(b);
                if (qualsA != null) {
                    java.util.Arrays.sort(qualsA, (x, y) -> x.toString().compareTo(y.toString()));
                }
                if (qualsB != null) {
                    java.util.Arrays.sort(qualsB, (x, y) -> x.toString().compareTo(y.toString()));
                }
                break;
            }
        }

        Assert.assertEquals(a, b);
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
//<fix end>

