Looking at the failure, the test fails because field iteration order from reflection is non-deterministic, causing columns and `<if>` blocks to appear in different orders. The previous fix weakened assertions by reconstructing SQL strings, losing exact format verification.

The solution is to:
1. Parse the generated SQL to extract columns and `<if>` blocks
2. Verify each component individually with exact format matching (order-insensitive)
3. Verify structural integrity (counts, no unexpected elements)
4. Sort ResultMappings by property for deterministic access while preserving all original assertions

//<fix start>
    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // Verify overall SQL structure
        Assert.assertTrue("SQL should start with 'SELECT '", sql.startsWith("SELECT "));
        Assert.assertTrue("SQL should contain '  FROM user '", sql.contains("  FROM user "));
        Assert.assertTrue("SQL should contain '<where>'", sql.contains("<where>"));
        Assert.assertTrue("SQL should end with '</where>'", sql.endsWith("</where>"));

        // Parse and verify SELECT columns (order-insensitive, exact format)
        int selectIdx = sql.indexOf("SELECT ") + 7;
        int fromIdx = sql.indexOf("  FROM");
        String actualSelect = sql.substring(selectIdx, fromIdx).trim();
        String[] actualColArray = actualSelect.split(",");
        Assert.assertEquals("Should have exactly 4 columns", 4, actualColArray.length);

        List<String> expectedCols = Arrays.asList("id", "user_name", "address", "state");
        List<String> actualCols = Arrays.asList(actualColArray);

        // Verify each expected column is present with exact format
        for (String expectedCol : expectedCols) {
            boolean found = false;
            for (String actualCol : actualCols) {
                if (actualCol.equals(expectedCol)) {
                    found = true;
                    break;
                }
            }
            Assert.assertTrue("Expected column not found: " + expectedCol, found);
        }

        // Verify no unexpected columns
        for (String actualCol : actualCols) {
            boolean found = false;
            for (String expectedCol : expectedCols) {
                if (actualCol.equals(expectedCol)) {
                    found = true;
                    break;
                }
            }
            Assert.assertTrue("Unexpected column found: " + actualCol, found);
        }

        // Parse and verify <if> blocks (order-insensitive, exact format)
        int whereStartIdx = sql.indexOf("<where>") + 7;
        int whereEndIdx = sql.indexOf("</where>");
        String actualWhere = sql.substring(whereStartIdx, whereEndIdx);

        List<String> expectedIfs = Arrays.asList(
                "<if test=\"id != null\"> AND id = #{id}</if>",
                "<if test=\"userName != null\"> AND user_name = #{userName}</if>",
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>",
                "<if test=\"state != null\"> AND state = #{state}</if>"
        );

        List<String> actualIfs = new ArrayList<String>();
        int start = 0;
        while (start < actualWhere.length()) {
            int end = actualWhere.indexOf("</if>", start) + 5;
            actualIfs.add(actualWhere.substring(start, end));
            start = end;
        }

        Assert.assertEquals("Should have exactly 4 <if> blocks", 4, actualIfs.size());

        // Verify each expected <if> block is present with exact format
        for (String expectedIf : expectedIfs) {
            boolean found = false;
            for (String actualIf : actualIfs) {
                if (actualIf.equals(expectedIf)) {
                    found = true;
                    break;
                }
            }
            Assert.assertTrue("Expected <if> block not found: " + expectedIf, found);
        }

        // Verify no unexpected <if> blocks
        for (String actualIf : actualIfs) {
            boolean found = false;
            for (String expectedIf : expectedIfs) {
                if (actualIf.equals(expectedIf)) {
                    found = true;
                    break;
                }
            }
            Assert.assertTrue("Unexpected <if> block found: " + actualIf, found);
        }

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals("Should have exactly 4 result mappings", 4, resultMappings.size());

        // Sort mappings by property name for order-insensitive comparison
        List<ResultMapping> sortedMappings = new ArrayList<ResultMapping>(resultMappings);
        Collections.sort(sortedMappings, new Comparator<ResultMapping>() {
            @Override
            public int compare(ResultMapping o1, ResultMapping o2) {
                return o1.getProperty().compareTo(o2.getProperty());
            }
        });

        // After sorting alphabetically: address, id, state, userName
        final ResultMapping addressMapping = sortedMappings.get(0);
        final ResultMapping idMapping = sortedMappings.get(1);
        final ResultMapping stateMapping = sortedMappings.get(2);
        final ResultMapping userNameMapping = sortedMappings.get(3);

        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
