    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        List<String> actualIfs = new ArrayList<>();
        String temp = whereAllIfColumns;
        while (temp.contains("<if")) {
            int start = temp.indexOf("<if");
            int end = temp.indexOf("</if>") + 5;
            actualIfs.add(temp.substring(start, end));
            temp = temp.substring(0, start) + temp.substring(end);
        }
        Collections.sort(actualIfs);
        List<String> expectedIfs = Arrays.asList(
            "<if test=\"id != null\"> AND id = #{id}</if>",
            "<if test=\"username != null\"> AND username = #{username}</if>"
        );
        Collections.sort(expectedIfs);
        Assert.assertEquals(expectedIfs, actualIfs);
        Assert.assertEquals("<where> AND is_valid = 1</where>", temp);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertTrue(updateSetColumns.startsWith("<set>"));
        Assert.assertTrue(updateSetColumns.endsWith("</set>"));
        String inner = updateSetColumns.substring(5, updateSetColumns.length() - 6);
        String[] parts = inner.split(",");
        List<String> actualParts = new ArrayList<>();
        for (String part : parts) {
            if (!part.isEmpty()) {
                actualParts.add(part);
            }
        }
        Collections.sort(actualParts);
        List<String> expectedParts = Arrays.asList("username = #{username}", "is_valid = 1");
        Collections.sort(expectedParts);
        Assert.assertEquals(expectedParts, actualParts);
    }
